// TestShikimoriJoint — enrichment box 6.1, the Tier-1 joint round trip
// (async-enrichment "Joint round trip" scenario). REAL plugin SUBPROCESSES
// (serial-parser, frame-grabber, shikimori — the serial chain at priorities
// 1-3) over the REAL composed graph (pbWorld: store, serial seed v2 registry,
// real scan, api+web over real HTTP) and the REAL enrich.Queue wired exactly
// as cmd/mellifera wires it — FetchGate included — with the scan Notify hook
// mirrored from main.go. shikimori.io stands in NEVER: an httptest stub
// upstream serves the anime payloads, and the core-side fetch is pointed at
// it by rewriting the shikimori.io host at the transport (the plugin's API
// base is a compile-time constant; the transport swap is the one injection
// the black-box joint allows — restored on cleanup, and no test in this
// package runs parallel).
//
// The round trip: a serial library scans → both series rows drain through
// serial-parser → shikimori (fetch paced by the REAL gate) → RU-first
// namespaces + identifiers.shikimori_id anchors land → a seeded failure
// ledger row for one pair → ReenrichSource (whole-library sweep: both rows
// stripped, ledger cleared, identifiers preserved) → the drain re-fetches
// ANCHORED (GET /api/animes/{id}, the anchor drove the second Match) and
// fresh namespaces land.
//
// CONTRACT MISMATCH (expected red until the implementation fix lands; the
// test asserts the CONTRACT, never the buggy reality): on a REAL serial row
// the shikimori stage SKIPS with "no display title in document" and the row
// settles ready with no namespace. Chain of evidence: the scanner stamps
// record parsed WITHOUT a title (plugins/serial-scanner/scanner.go, fileFacts.parsed
// — serial_record/dir_name_raw/backing/series_relative_path/series_sidecars
// only); the chain hands EVERY source the same base built from doc["parsed"]
// alone (internal/enrich/worker.go reconstructBase; internal/enrich/chain.go
// runSource), and applyContribution (internal/enrich/enrich.go) never writes
// parsed — so serial-parser's derived title (sources.serial-parser) can
// never reach shikimori's Match, which reads only
// Item.Parsed[title] (plugins/shikimori/source.go — the empty-title guard).
// The plugin's package TestMatch passes because its fixtures feed synthetic
// parsed maps that already carry title+season — a shape no real scan
// produces. Escalated to the session; fix ownership is outside the QA
// editable set.
package itest

import (
	"context"
	"encoding/json"
	"io"
	"net/http"
	"net/http/httptest"
	"net/url"
	"os/exec"
	"path/filepath"
	"regexp"
	"strconv"
	"strings"
	"sync"
	"testing"
	"time"

	"github.com/mellifera/mellifera/internal/enrich"
	"github.com/mellifera/mellifera/pkg/sdk"
)

// Fixture identity constants (no-coincidence discipline: independent of the
// plugin suites' fixtures) and the shikimori contract constants re-derived
// from the plugin's shipped values.
const (
	qaShikDirA     = "Cowboy Bebop S01"
	qaShikDirB     = "Trigun S01"
	qaShikTitleA   = "Cowboy Bebop" // dir A under the shared grammar's season cut
	qaShikTitleB   = "Trigun"
	qaShikRomajiA  = "Cowboy Bebop"
	qaShikRussianA = "Ковбой Бибоп"
	qaShikRomajiB  = "Trigun"
	qaShikRussianB = "Триган"
	qaShikIDa      = 4242 // row A's anime (search hit → selected; then anchored)
	qaShikIDb      = 4244 // row B's anime
	qaShikUA       = "mellifera/"
	qaShikInterval = 700 * time.Millisecond // the spec's min_interval_ms
	// qaShikSlop absorbs stub-side arrival jitter (ms-scale on localhost);
	// a gate-less burst arrives within single-digit ms, so the 650ms floor
	// still detects it with orders of magnitude to spare.
	qaShikSlop = 50 * time.Millisecond
	qaShikHost = "shikimori.io"
	qaShikAPI  = "/api/animes"
)

// qaShikWant is one row's upstream expectation — the stub fixture's values
// projected into the namespace assertions.
type qaShikWant struct {
	id, episodes           int
	romaji, russian, aired string
	score                  float64
}

var (
	qaShikWantA = qaShikWant{id: qaShikIDa, episodes: 26, romaji: qaShikRomajiA, russian: qaShikRussianA, aired: "1998-04-03", score: 8.6}
	qaShikWantB = qaShikWant{id: qaShikIDb, episodes: 26, romaji: qaShikRomajiB, russian: qaShikRussianB, aired: "1998-04-01", score: 8.4}
)

// qaShikAnime builds one upstream anime payload (the v1 shape Convert
// decodes; score is a decimal STRING upstream).
func qaShikAnime(id int, name, russian, kind string, episodes int, aired, score string) map[string]any {
	return map[string]any{
		"id": id, "name": name, "russian": russian, "kind": kind, "status": "released",
		"score": score, "episodes": episodes, "aired_on": aired,
		"description": "qa stub " + name,
		"url":         qaShikAPI + "/" + strconv.Itoa(id) + "-qa",
		"image":       map[string]any{"original": "/images/animes/" + strconv.Itoa(id) + ".jpg"},
		"genre": []any{
			map[string]any{"name": "Action", "russian": "Экшен"},
			map[string]any{"name": "Sci-Fi", "russian": "Фантастика"},
		},
	}
}

// qaShikSearchList serves the per-title search lists: candidate 0 is the
// right anime, candidate 1 a movie decoy the preference score must not pick
// when the serial-record query carries none of the scored facts.
var qaShikSearchList = map[string][]map[string]any{
	qaShikTitleA: {
		qaShikAnime(qaShikIDa, qaShikRomajiA, qaShikRussianA, "tv", 26, qaShikWantA.aired, "8.6"),
		qaShikAnime(qaShikIDa+1, "Cowboy Bebop The Movie", "Ковбой Бибоп фильм", "movie", 1, "2001-09-01", "8.1"),
	},
	qaShikTitleB: {
		qaShikAnime(qaShikIDb, qaShikRomajiB, qaShikRussianB, "tv", 26, qaShikWantB.aired, "8.4"),
		qaShikAnime(qaShikIDb+1, "Trigun Badlands Rumble", "Триган Румбл", "movie", 1, "2010-04-24", "7.9"),
	},
}

// qaShikByID serves the anchored by-id fetches (the single-object shape).
var qaShikByID = map[string]map[string]any{
	strconv.Itoa(qaShikIDa): qaShikAnime(qaShikIDa, qaShikRomajiA, qaShikRussianA, "tv", 26, qaShikWantA.aired, "8.6"),
	strconv.Itoa(qaShikIDb): qaShikAnime(qaShikIDb, qaShikRomajiB, qaShikRussianB, "tv", 26, qaShikWantB.aired, "8.4"),
}

// qaShikReq is one upstream request the stub recorded.
type qaShikReq struct {
	method, path, query, ua string
	at                      time.Time
}

// qaShikGraphQLIDRe pulls the anchored id out of the GraphQL poster leg's
// POST body ({animes(ids:"N"){poster{originalUrl}}}).
var qaShikGraphQLIDRe = regexp.MustCompile(`ids:\\"(\d+)\\"`)

// qaShikStub is the fake upstream: it records every request and serves the
// anime payloads above.
type qaShikStub struct {
	srv  *httptest.Server
	mu   sync.Mutex
	seen []qaShikReq
}

func qaShikStartStub(t *testing.T) *qaShikStub {
	t.Helper()
	s := &qaShikStub{}
	mux := http.NewServeMux()
	mux.HandleFunc(qaShikAPI, func(w http.ResponseWriter, r *http.Request) {
		s.record(r)
		list, ok := qaShikSearchList[r.URL.Query().Get("search")]
		if !ok {
			http.NotFound(w, r)
			return
		}
		qaShikWriteJSON(t, w, list)
	})
	mux.HandleFunc(qaShikAPI+"/", func(w http.ResponseWriter, r *http.Request) {
		s.record(r)
		e, ok := qaShikByID[strings.TrimPrefix(r.URL.Path, qaShikAPI+"/")]
		if !ok {
			http.NotFound(w, r)
			return
		}
		qaShikWriteJSON(t, w, e)
	})
	// The GraphQL poster leg (artwork 2026-10-27): the anchored plan's
	// extras[2] POSTs {animes(ids:"N"){poster{originalUrl}}} — answer with
	// the new-poster-system URL for the requested id so the e2e covers the
	// fallback contract end to end.
	mux.HandleFunc("/api/graphql", func(w http.ResponseWriter, r *http.Request) {
		s.record(r)
		body, _ := io.ReadAll(r.Body)
		m := qaShikGraphQLIDRe.FindSubmatch(body)
		if m == nil {
			http.NotFound(w, r)
			return
		}
		qaShikWriteJSON(t, w, map[string]any{
			"data": map[string]any{
				"animes": []any{map[string]any{
					"poster": map[string]any{
						"originalUrl": "/uploads/poster/animes/" + string(m[1]) + "/qa-main.webp",
					},
				}},
			},
		})
	})
	s.srv = httptest.NewServer(mux)
	t.Cleanup(s.srv.Close)
	return s
}

func (s *qaShikStub) record(r *http.Request) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.seen = append(s.seen, qaShikReq{
		method: r.Method, path: r.URL.Path, query: r.URL.RawQuery,
		ua: r.Header.Get("User-Agent"), at: time.Now(),
	})
}

func (s *qaShikStub) requests() []qaShikReq {
	s.mu.Lock()
	defer s.mu.Unlock()
	return append([]qaShikReq(nil), s.seen...)
}

// qaShikRewrite points the core's fetch at the stub: upstream-host requests
// keep their path/query/headers but hit the stub. Everything else (the api
// surface, the plugin gRPC) passes through untouched.
type qaShikRewrite struct {
	stub *url.URL
	next http.RoundTripper
}

func (r *qaShikRewrite) RoundTrip(req *http.Request) (*http.Response, error) {
	if req.URL.Hostname() == qaShikHost {
		clone := req.Clone(req.Context())
		clone.URL.Scheme, clone.URL.Host = r.stub.Scheme, r.stub.Host
		req = clone
	}
	return r.next.RoundTrip(req)
}

// qaShikJoint is one composed joint round trip.
type qaShikJoint struct {
	w    *pbWorld
	q    *enrich.Queue
	stub *qaShikStub
	lib  int64
}

// qaShikStartJoint composes the joint: the pbWorld graph + the three
// metadata plugin subprocesses + the real queue (the real FetchGate — the
// cmd/mellifera wiring shape, never nil) + the scan Notify hook (the
// main.go scanDeps.Notify shape, mirrored in miniature per the harness
// contract).
func qaShikStartJoint(t *testing.T) *qaShikJoint {
	t.Helper()
	if _, err := exec.LookPath("ffmpeg"); err != nil {
		t.Skipf("shikimori joint needs ffmpeg on PATH (episode fixtures are lavfi-generated): %v", err)
	}
	w := pbNewWorld(t)
	tmp := t.TempDir()
	metaCaps := []sdk.Capability{{Type: "metadata_source", ID: "default", ProtoService: "mellifera.metadata.v1.MetadataSource"}}
	paths := map[string]string{
		"serial-parser": buildBinary(t, tmp, "qa-shik-serial-parser", "./plugins/serial-parser"),
		"frame-grabber": buildBinary(t, tmp, "qa-shik-frame-grabber", "./plugins/frame-grabber"),
		"shikimori":     buildBinary(t, tmp, "qa-shik-shikimori", "./plugins/shikimori"),
	}
	for id, path := range paths {
		if err := w.mgr.Load(id, path, metaCaps); err != nil {
			t.Fatalf("load %s: %v", id, err)
		}
		if err := w.mgr.Start(context.Background(), id); err != nil {
			t.Fatalf("start %s: %v", id, err)
		}
	}
	t.Cleanup(func() {
		stopCtx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
		defer cancel()
		for id := range paths {
			_ = w.mgr.Stop(stopCtx, id)
		}
	})

	j := &qaShikJoint{w: w, stub: qaShikStartStub(t)}
	deps := enrich.Deps{Store: w.st, Modules: w.reg, Plugins: w.mgr, FetchGate: enrich.NewFetchGate()}
	j.q = enrich.NewQueue(deps, enrich.QueueConfig{Workers: 2, Backoff: 10 * time.Millisecond})
	if err := j.q.Start(context.Background()); err != nil {
		t.Fatalf("queue start: %v", err)
	}
	t.Cleanup(j.q.Stop)
	// The scan Notify hook — main.go's shape, INCLUDING its context rule
	// (main.go INV-context-shared): the closure substitutes the joint's own
	// context for the per-request scan ctx, or the feeder aborts the moment
	// the scan handler returns and nothing ever drains.
	w.scanDep.Notify = func(ctx context.Context, libraryID int64) {
		j.q.Notify(context.WithoutCancel(ctx), libraryID)
	}

	// The stub host swap: no test in this package sets t.Parallel, and the
	// cleanup restores before any later test in the binary runs.
	saved := http.DefaultTransport
	stubURL, err := url.Parse(j.stub.srv.URL)
	if err != nil {
		t.Fatalf("parse stub url: %v", err)
	}
	http.DefaultTransport = &qaShikRewrite{stub: stubURL, next: saved}
	t.Cleanup(func() { http.DefaultTransport = saved })

	root := t.TempDir()
	qaSerialMedia(t, filepath.Join(root, qaShikDirA, "Cowboy Bebop S01E01.mkv"))
	qaSerialMedia(t, filepath.Join(root, qaShikDirB, "Trigun S01E01.mkv"))
	j.lib = qaSerialCreateLibrary(t, w.client, w.baseURL, w.token, root, "QA Shikimori Joint")
	return j
}

// TestShikimoriJoint is the Tier-1 joint round trip over the real chain.
func TestShikimoriJoint(t *testing.T) {
	if testing.Short() {
		t.Skip("shikimori joint: skips under -short (builds binaries + subprocesses)")
	}
	j := qaShikStartJoint(t)
	scanRes := pbScanLibrary(t, j.w, j.lib)
	if len(scanRes.Warnings) > 0 {
		t.Logf("scan warnings: %v", scanRes.Warnings)
	}
	if scanRes.Persisted == 0 {
		t.Fatalf("scan persisted nothing: %+v", scanRes)
	}

	// --- leg 1: the first enrichment — search fetch, paced, anchors land ---
	// (Expected failure site under the CONTRACT MISMATCH documented atop the
	// file: the await times out and dumps the doc — its _stages show the
	// shikimori stage skipped. Do NOT weaken this into asserting the skip.)
	seriesA := qaShikAwaitNamespace(t, j, qaShikDirA)
	seriesB := qaShikAwaitNamespace(t, j, qaShikDirB)
	qaShikAssertNamespace(t, j, seriesA, qaShikWantA)
	qaShikAssertNamespace(t, j, seriesB, qaShikWantB)
	qaShikAssertSearchLeg(t, j, 2, []string{qaShikTitleA, qaShikTitleB})

	// --- the seeded failure: a within-cooldown ledger row for one pair ---
	ctx := context.Background()
	if err := j.w.st.RecordFailure(ctx, seriesA, "shikimori", "exhausted", "qa seeded failure", 2,
		time.Now().Add(time.Hour)); err != nil {
		t.Fatalf("seed ledger row: %v", err)
	}
	qaShikAssertLedger(t, j, map[string]bool{seriesA: true})

	// --- leg 2: the sweep — strip both, clear the ledger, drain re-fetches anchored ---
	stripped, deferred, err := j.q.ReenrichSource(ctx, j.lib, "shikimori")
	if err != nil {
		t.Fatalf("ReenrichSource: %v", err)
	}
	if stripped != 2 || deferred != 0 {
		t.Fatalf("ReenrichSource = stripped %d deferred %d, want 2/0 (both series rows carry the namespace)", stripped, deferred)
	}
	qaShikAssertLedger(t, j, map[string]bool{})
	qaShikAssertNamespace(t, j, qaShikAwaitNamespace(t, j, qaShikDirA), qaShikWantA)
	qaShikAssertNamespace(t, j, qaShikAwaitNamespace(t, j, qaShikDirB), qaShikWantB)
	// want-total 10 = 2 ids x 4 requests (by-id + /roles + /episodes +
	// the GraphQL poster POST): the second anchored extra (/episodes) is
	// sanctioned by openspec change episode-titles (shikimori-enrichment
	// delta); the third (GraphQL poster) closes the REST image false
	// negative for the new poster system (artwork).
	qaShikAssertAnchoredLeg(t, j, 10, qaShikIDa, qaShikIDb)
}

// qaShikAwaitNamespace polls the series rows until the dir's row settles
// ready with its shikimori namespace landed, returning the series id. The
// failure dump carries the raw document — its _stages carry a skipped
// stage's reason, the diagnosis surface.
func qaShikAwaitNamespace(t *testing.T, j *qaShikJoint, dir string) string {
	t.Helper()
	deadline := time.Now().Add(qaSerialDrainTimeout)
	for time.Now().Before(deadline) {
		for _, sr := range qaSerialListSeries(t, j.w.client, j.w.baseURL, j.w.token, j.lib) {
			if sr.RelativePath != dir || sr.Status != "ready" {
				continue
			}
			if parseAsyncDoc(t, sr.Document).Sources["shikimori"] != nil {
				return sr.ID
			}
		}
		time.Sleep(probeInterval)
	}
	st := j.q.Stats()
	items := listItems(t, j.w.client, j.w.baseURL, j.w.token, j.lib)
	itemStates := make([]string, 0, len(items))
	for _, it := range items {
		itemStates = append(itemStates, it.RelativePath+"="+it.Status)
	}
	for _, sr := range qaSerialListSeries(t, j.w.client, j.w.baseURL, j.w.token, j.lib) {
		if sr.RelativePath == dir {
			t.Fatalf("series %q: shikimori namespace never landed (status %s); queue stats %+v; items %v; doc:\n%s",
				dir, sr.Status, st, itemStates, sr.Document)
		}
	}
	t.Fatalf("series %q missing from library %d", dir, j.lib)
	return ""
}

// qaShikAssertNamespace pins the namespace contract of the round trip: the
// selected candidate's RU-first payload, resolved_ids stripped from the
// namespace (it lives only in identifiers), the identifiers anchor, and the
// shikimori provenance. Re-run after the sweep, it is the FRESH namespace.
func qaShikAssertNamespace(t *testing.T, j *qaShikJoint, seriesID string, want qaShikWant) {
	t.Helper()
	sr, status, errCode := qaSerialGetSeries(t, j.w.client, j.w.baseURL, j.w.token, seriesID)
	if status != http.StatusOK {
		t.Fatalf("GET series %s: HTTP %d (%s)", seriesID, status, errCode)
	}
	doc := parseAsyncDoc(t, sr.Document)
	ns, ok := doc.Sources["shikimori"]
	if !ok {
		t.Fatalf("series %s: sources.shikimori missing; doc:\n%s", seriesID, sr.Document)
	}
	title, _ := ns["title"].(map[string]any)
	if asyncStr(title, "romaji") != want.romaji || asyncStr(title, "russian") != want.russian {
		t.Errorf("sources.shikimori.title = %v, want {romaji:%s russian:%s} (RU-first, anime %d)", title, want.romaji, want.russian, want.id)
	}
	if asyncStr(ns, "kind") != "tv" || asyncStr(ns, "status") != "released" {
		t.Errorf("sources.shikimori kind/status = %q/%q, want tv/released (candidate %d, not the movie decoy)",
			asyncStr(ns, "kind"), asyncStr(ns, "status"), want.id)
	}
	if n, _ := ns["episodes"].(float64); int(n) != want.episodes {
		t.Errorf("sources.shikimori.episodes = %v, want %d", ns["episodes"], want.episodes)
	}
	if asyncStr(ns, "aired_on") != want.aired {
		t.Errorf("sources.shikimori.aired_on = %q, want %q", asyncStr(ns, "aired_on"), want.aired)
	}
	if s, _ := ns["score"].(float64); s != want.score {
		t.Errorf("sources.shikimori.score = %v, want %v (upstream string decoded to a number)", ns["score"], want.score)
	}
	qaShikAssertGenres(t, ns)
	if asyncStr(ns, "description") == "" {
		t.Errorf("sources.shikimori.description missing: %v", ns["description"])
	}
	if got := asyncStr(ns, "url"); got != "https://"+qaShikHost+qaShikAPI+"/"+strconv.Itoa(want.id)+"-qa" {
		t.Errorf("sources.shikimori.url = %q, want the absolute upstream url of anime %d", got, want.id)
	}
	if got := asyncStr(ns, "poster"); got != "https://"+qaShikHost+"/images/animes/"+strconv.Itoa(want.id)+".jpg" {
		t.Errorf("sources.shikimori.poster = %q, want the absolute image url of anime %d", got, want.id)
	}
	if _, leaked := ns["resolved_ids"]; leaked {
		t.Errorf("sources.shikimori carries resolved_ids: %v (it must live only in identifiers)", ns["resolved_ids"])
	}
	qaShikAssertIdentifier(t, sr.Document, want.id)
	if asyncStr(doc.Provenance["title"], "plugin_id") != "shikimori" {
		t.Errorf("_provenance.title = %v, want a shikimori entry", doc.Provenance["title"])
	}
}

// qaShikAssertGenres checks the RU-first genre projection (russian names, in
// upstream order).
func qaShikAssertGenres(t *testing.T, ns map[string]any) {
	t.Helper()
	genres, _ := ns["genres"].([]any)
	want := []string{"Экшен", "Фантастика"}
	if len(genres) != len(want) {
		t.Errorf("sources.shikimori.genres = %v, want %v", genres, want)
		return
	}
	for i, g := range genres {
		if got, _ := g.(string); got != want[i] {
			t.Errorf("sources.shikimori.genres[%d] = %q, want %q", i, got, want[i])
		}
	}
}

// qaShikAssertIdentifier decodes the document's identifiers region and pins
// the anchor (never stripped by the sweep — leg 2 re-asserts it).
func qaShikAssertIdentifier(t *testing.T, raw json.RawMessage, wantID int) {
	t.Helper()
	var doc map[string]any
	if err := json.Unmarshal(raw, &doc); err != nil {
		t.Fatalf("decode doc: %v", err)
	}
	ids, _ := doc["identifiers"].(map[string]any)
	if got, _ := ids["shikimori_id"].(float64); int(got) != wantID {
		t.Errorf("identifiers.shikimori_id = %v, want %d (the anchor)", ids["shikimori_id"], wantID)
	}
}

// qaShikAssertSearchLeg pins the search-leg upstream contract at the
// checkpoint count: exactly wantTotal recorded requests, every one a GET on
// the search endpoint whose decoded search param covers exactly titles (one
// per row), the bounded page size present, the application UA (never a
// library default — shikimori.io bans those), and consecutive sends spaced
// at least min_interval apart (the REAL gate's contract; the two rows drain
// concurrently, so without the gate the pair arrives in a burst).
func qaShikAssertSearchLeg(t *testing.T, j *qaShikJoint, wantTotal int, titles []string) {
	t.Helper()
	reqs := j.stub.requests()
	if len(reqs) != wantTotal {
		t.Fatalf("upstream saw %d requests, want %d: %+v", len(reqs), wantTotal, reqs)
	}
	seen := map[string]bool{}
	for i, r := range reqs {
		if r.method != http.MethodGet || r.path != qaShikAPI {
			t.Errorf("request %d: %s %s, want GET %s", i, r.method, r.path, qaShikAPI)
		}
		qaShikAssertUA(t, i, r.ua)
		qaShikAssertPacing(t, i, reqs)
		q, err := url.ParseQuery(r.query)
		if err != nil {
			t.Errorf("request %d: bad query %q: %v", i, r.query, err)
			continue
		}
		if q.Get("limit") == "" {
			t.Errorf("request %d: search query %q carries no bounded page size", i, r.query)
		}
		seen[q.Get("search")] = true
	}
	for _, title := range titles {
		if !seen[title] {
			t.Errorf("no search request for title %q; searches seen: %v", title, seen)
		}
	}
	if len(seen) != len(titles) {
		t.Errorf("search requests cover %v, want exactly %v", seen, titles)
	}
}

// qaShikAssertAnchoredLeg pins the second leg's upstream contract: the tail
// requests after the sweep hit the BY-ID endpoints — four per id (the by-id
// fetch, its /roles request-plan companion, its /episodes fetch, and the
// GraphQL poster POST — the extras request sanctioned by the artwork poster
// fallback), as a set (rows drain concurrently) — proving
// identifiers.shikimori_id anchored the second Match (the search endpoint is
// never hit again).
func qaShikAssertAnchoredLeg(t *testing.T, j *qaShikJoint, wantTotal int, ids ...int) {
	t.Helper()
	reqs := j.stub.requests()
	if len(reqs) != wantTotal {
		t.Fatalf("upstream saw %d requests, want %d: %+v", len(reqs), wantTotal, reqs)
	}
	tail := reqs[len(reqs)-4*len(ids):]
	paths := map[string]bool{}
	for _, id := range ids {
		paths[qaShikAPI+"/"+strconv.Itoa(id)] = false
		paths[qaShikAPI+"/"+strconv.Itoa(id)+"/roles"] = false
		paths[qaShikAPI+"/"+strconv.Itoa(id)+"/episodes"] = false
		paths["/api/graphql"] = false
	}
	for i, r := range tail {
		// The three REST legs are GETs; the GraphQL poster leg is the one
		// sanctioned POST.
		if want := map[string]string{"/api/graphql": http.MethodPost}[r.path]; want == "" {
			if r.method != http.MethodGet {
				t.Errorf("anchored request %d: %s %s, want GET", i, r.method, r.path)
			}
		} else if r.method != want {
			t.Errorf("anchored request %d: %s %s, want %s", i, r.method, r.path, want)
		}
		qaShikAssertUA(t, i, r.ua)
		qaShikAssertPacing(t, i, tail)
		if _, hit := paths[r.path]; hit {
			paths[r.path] = true
		} else {
			t.Errorf("anchored request %d hit %s, want one of the by-id endpoints %v", i, r.path, paths)
		}
	}
	for path, hit := range paths {
		if !hit {
			t.Errorf("no anchored fetch for %s (the anchor must drive the second match)", path)
		}
	}
}

// qaShikAssertUA pins the application UA header (version-agnostic: the
// contract is "names THIS application", never a library default).
func qaShikAssertUA(t *testing.T, i int, ua string) {
	t.Helper()
	if !strings.HasPrefix(ua, qaShikUA) {
		t.Errorf("request %d: User-Agent = %q, want the mellifera application UA", i, ua)
	}
}

// qaShikAssertPacing pins the fetch gate on one recorded request: its send
// is at least min_interval after its predecessor (allowing the stub-side
// arrival slop). First-in-list is unbounded (a first send never waits).
func qaShikAssertPacing(t *testing.T, i int, reqs []qaShikReq) {
	t.Helper()
	if i == 0 {
		return
	}
	if gap := reqs[i].at.Sub(reqs[i-1].at); gap < qaShikInterval-qaShikSlop {
		t.Errorf("request %d arrived %v after request %d, want >= %v (the fetch gate must pace sends)",
			i, gap, i-1, qaShikInterval-qaShikSlop)
	}
}

// qaShikAssertLedger pins the shikimori ledger rows: exactly the series ids
// in want (the seeded row before the sweep, none after).
func qaShikAssertLedger(t *testing.T, j *qaShikJoint, want map[string]bool) {
	t.Helper()
	rows, err := j.w.st.ListFailures(context.Background())
	if err != nil {
		t.Fatalf("ListFailures: %v", err)
	}
	got := map[string]bool{}
	for _, r := range rows {
		if r.PluginID == "shikimori" {
			got[r.ItemID] = true
		}
	}
	for id := range got {
		if !want[id] {
			t.Errorf("unexpected shikimori ledger row for %q (want %v)", id, want)
		}
	}
	for id := range want {
		if !got[id] {
			t.Errorf("shikimori ledger row for %q missing (have %v)", id, got)
		}
	}
}

func qaShikWriteJSON(t *testing.T, w http.ResponseWriter, v any) {
	t.Helper()
	w.Header().Set("Content-Type", "application/json")
	if err := json.NewEncoder(w).Encode(v); err != nil {
		t.Errorf("stub write: %v", err)
	}
}
